'use strict';
(()=>{
  const el=id=>document.getElementById(id),home=el('focus-overview');
  const heading=(tool,title,glyph)=>`<header><span>${icon(glyph)}<strong>${title}</strong></span><button type="button" data-open-tool="${tool}" aria-label="Open ${title}" title="Open ${title}">${icon('arrow-up-right')}</button></header>`;
  home.innerHTML=`
    <article class="focus-tile music-tile" aria-label="Music preview">
      <header><span>${icon('music')}<strong>Music</strong></span></header>
      <div class="bento-player music-preview"><div class="bento-record" aria-hidden="true"><span></span></div><div class="bento-copy"><strong id="bento-music-title">Your soundtrack</strong><small id="bento-music-state">Choose something to play</small></div><button id="bento-music-play" class="bento-play" type="button" aria-label="Open music player">${icon('play')}</button></div>
      <form id="bento-music-form" class="bento-link-form bento-music-form" novalidate><div class="music-service-picker"><span class="service-dot" aria-hidden="true"></span><label class="sr-only" for="bento-music-service">Music service</label><select id="bento-music-service" aria-label="Music service"><option value="spotify">Spotify</option><option value="apple">Apple Music</option><option value="youtube">YouTube Music</option></select></div><label for="bento-music-link" class="sr-only">Music link</label><input id="bento-music-link" placeholder="Paste a music link…" maxlength="2048" autocomplete="off" spellcheck="false" aria-describedby="bento-music-error"><button id="bento-music-open" type="submit" aria-label="Open music player" title="Open music player">${icon('arrow-up-right')}</button><button id="bento-music-account" type="button" aria-label="Music account" title="Music account">${icon('lock')}</button></form><span id="bento-music-error" role="alert" hidden></span><div id="bento-music-volume"></div>
    </article>
    <article class="focus-tile timer-tile" aria-label="Timer preview">
      ${heading('focus','Timer','focus')}
      <div id="bento-agenda" class="bento-agenda"><div class="bento-clock"><span id="bento-clock" role="timer" aria-live="off"></span><button id="bento-timer-play" class="bento-play" type="button" aria-label="Start focus">${icon('play')}</button></div><small id="bento-timer-topic"></small><div class="bento-options bento-durations" role="group" aria-label="Quick focus duration"><button data-focus-minutes="15">15<span> min</span></button><button data-focus-minutes="30">30<span> min</span></button><button data-focus-minutes="45">45<span> min</span></button><button data-focus-minutes="60">60<span> min</span></button></div></div>
      <section class="bento-plan-section" aria-label="Agenda preview"><header><button type="button" id="bento-agenda-open" class="bento-plan-link">Agenda</button><small id="bento-agenda-count"></small><button type="button" id="bento-agenda-new" aria-label="New agenda topic" title="New agenda topic">${icon('plus')}</button></header><div id="bento-agenda-topics"></div><form id="bento-topic-form" class="bento-quick-add"><label class="sr-only" for="bento-topic-name">New agenda topic</label><input id="bento-topic-name" maxlength="60" placeholder="New topic…" required><label class="sr-only" for="bento-topic-minutes">Topic minutes</label><input id="bento-topic-minutes" type="number" min="1" max="1440" value="5"><span>min</span><button type="submit" aria-label="Add agenda topic" title="Add agenda topic">${icon('plus')}</button></form><small id="bento-topic-help" role="status"></small></section>
      <section id="bento-calendar" class="bento-calendar bento-plan-section" aria-label="Calendar preview"><header><button type="button" id="bento-calendar-heading" class="bento-plan-link">Calendar</button><span id="bento-calendar-day"></span><button id="bento-calendar-new" type="button" aria-label="Add calendar session" title="Add calendar session">${icon('plus')}</button></header><div id="bento-calendar-week" aria-label="Schedule this week"></div><div id="bento-upcoming"></div><button id="bento-calendar-open" type="button" class="bento-text-action">Open calendar ${icon('chevron')}</button><form id="bento-event-form" hidden><label>Session<input id="bento-event-title" maxlength="80" placeholder="What will you work on?" required></label><label>When<input id="bento-event-time" type="datetime-local" required></label><div><label>Minutes<select id="bento-event-minutes"><option>15</option><option>30</option><option>45</option><option>60</option></select></label><button id="bento-event-cancel" type="button">Cancel</button><button type="submit">Schedule</button></div><small id="bento-event-error" role="alert" hidden></small></form></section>
    </article>
    <article class="focus-tile youtube-tile" aria-label="YouTube preview">
      ${heading('youtube','YouTube','play')}
      <div class="bento-player youtube-preview"><div class="bento-video-art" aria-hidden="true"><img id="bento-youtube-art" alt="" hidden>${icon('play')}</div><div class="bento-copy"><strong id="bento-youtube-title">Set the mood</strong><small id="bento-youtube-state">A video, a mix, a little inspiration.</small></div><button id="bento-youtube-play" class="bento-play" type="button" aria-label="Open YouTube player">${icon('play')}</button></div>
      <form id="bento-youtube-form" class="bento-link-form" novalidate><label for="bento-youtube-link" class="sr-only">YouTube link or search</label>${icon('link')}<input id="bento-youtube-link" placeholder="Paste a link or search…" maxlength="2048" autocomplete="off"><button type="submit" aria-label="Load or search YouTube" title="Load or search YouTube">${icon('arrow-up-right')}</button></form><span id="bento-youtube-error" role="alert" hidden></span><div id="bento-youtube-volume"></div>
    </article>
    <article class="focus-tile media-tile" aria-label="Local media preview">
      ${heading('media','Media','monitor')}
      <div id="bento-media-empty" class="bento-media-empty"><span class="bento-drop-icon" aria-hidden="true">${icon('folder')}</span><strong>Drop audio, video, or a folder</strong><small>Local files stay on this device.</small></div>
      <div id="bento-media-loaded" class="bento-media-loaded" hidden><div class="bento-carousel" aria-label="Loaded media"><button id="bento-media-prev" type="button" aria-label="Previous media preview">${icon('chevron')}</button><button id="bento-media-play" type="button" class="bento-media-art" aria-label="Play media"><canvas id="bento-media-video" aria-hidden="true" hidden></canvas><span data-play-icon>${icon('play')}</span></button><button id="bento-media-next" type="button" aria-label="Next media preview">${icon('chevron')}</button></div><strong id="bento-media-title"></strong><small id="bento-media-count"></small></div><div class="bento-media-import"><button id="bento-media-folder" type="button">${icon('folder')}<span>Open folder</span></button><button id="bento-media-files" type="button">${icon('plus')}<span>Choose files</span></button><small id="bento-drop-status" role="status">Or drag files onto this card</small></div><div id="bento-media-volume"></div>
    </article>`;
  let busy=new Set(),lastImage='',lastCalendar='',lastAgenda='',lastMedia=-1;
  function open(tool){changeScenario(tool);(tool==='focus'?el(window.OpenSesameFocusCalendar.snapshot().view==='calendar'?'focus-calendar-add':'focus-start'):el('lockin-'+tool))?.focus({preventScroll:true})}
  home.querySelectorAll('[data-open-tool]').forEach(b=>b.addEventListener('click',()=>open(b.dataset.openTool)));
  el('focus-overview-return').addEventListener('click',()=>{changeScenario('lockin');(state.lockinView==='music'?el('bento-music-open'):home.querySelector(`[data-open-tool="${state.lockinView}"]`))?.focus({preventScroll:true})});
  el('bento-music-service').addEventListener('change',event=>{window.OpenSesameMusic.choose(event.target.value);sync()});
  el('bento-music-link').addEventListener('input',()=>{el('bento-music-error').hidden=true;el('bento-music-link').removeAttribute('aria-invalid')});
  el('bento-music-form').addEventListener('submit',event=>{
    event.preventDefault();const input=el('bento-music-link'),value=input.value.trim();
    if(value&&!window.OpenSesameMusic.parse(value)){el('bento-music-error').textContent='Paste a Spotify, Apple Music, or YouTube Music link.';el('bento-music-error').hidden=false;input.setAttribute('aria-invalid','true');input.focus();return}
    if(value){el('music-url').value=value;el('music-source-form').requestSubmit();input.value=''}
    el('bento-music-error').hidden=true;open('music');
  });
  el('bento-music-account').addEventListener('click',()=>{open('music');el('music-account-toggle').click()});
  home.querySelectorAll('[data-focus-minutes]').forEach(b=>b.addEventListener('click',()=>{setFocusDuration(Number(b.dataset.focusMinutes));sync()}));
  el('bento-timer-play').addEventListener('click',()=>{el('focus-start').click();sync()});
  el('bento-calendar-open').addEventListener('click',()=>{changeScenario('focus');window.OpenSesameFocusCalendar.choose('calendar');el('focus-calendar-add').focus({preventScroll:true})});
  function musicProvider(){return window.OpenSesameMusic?.youtubeActive?window.OpenSesameYouTube:window.OpenSesameMusic}
  const volumes=[['music',musicProvider],['youtube',()=>window.OpenSesameYouTube],['media',()=>window.OpenSesameLocalMedia]].map(([key,provider])=>window.OpenSesameVolume.attach(el('bento-'+key+'-volume'),provider,key==='media'?'Local media':key==='youtube'?'YouTube':'Music'));
  const playbackText=data=>{const status=data.playing?'Playing':data.ready?'Paused':'Connecting';return status+(Number.isFinite(data.position)&&data.duration>0?' · '+time(data.position)+' / '+time(data.duration):'')};
  async function transport(key,provider,tool){if(busy.has(key))return;const media=provider?.snapshot();if(!media?.loaded||!media.ready){open(tool);return}busy.add(key);sync();try{await provider.control('toggle')}catch(error){toast(error.message||'Open the player to continue.')}finally{busy.delete(key);sync()}}
  el('bento-music-play').addEventListener('click',()=>transport('music',musicProvider(),'music'));
  el('bento-youtube-play').addEventListener('click',()=>transport('youtube',window.OpenSesameYouTube,'youtube'));
  el('bento-media-play').addEventListener('click',()=>transport('media',window.OpenSesameLocalMedia,'media'));
  el('bento-youtube-link').addEventListener('input',()=>{el('bento-youtube-error').hidden=true});
  el('bento-youtube-form').addEventListener('submit',event=>{
    event.preventDefault();const query=el('bento-youtube-link').value.trim(),source=OpenSesamePlaylist.parseSource(query);
    el('bento-youtube-error').hidden=true;
    if(!query)return;
    if(source){el('youtube-url').value=query;window.OpenSesameYouTube.open(source);open('youtube');return}
    if(/^(?:[a-z]+:|www\.|youtu(?:be)?\.)/i.test(query)){el('bento-youtube-error').textContent='Use a YouTube video or playlist link.';el('bento-youtube-error').hidden=false;return}
    window.open('https://www.youtube.com/results?search_query='+encodeURIComponent(query),'_blank','noopener,noreferrer');
  });
  el('bento-media-folder').addEventListener('click',()=>el('media-folder').click());
  el('bento-media-files').addEventListener('click',()=>el('media-file').click());
  el('bento-topic-form').addEventListener('submit',event=>{event.preventDefault();if(focusRunning||focusTopics.length>=topicLimit())return;el('topic-name').value=el('bento-topic-name').value;el('topic-minutes').value=el('bento-topic-minutes').value;el('topic-form').requestSubmit();el('bento-topic-name').value='';sync();el('bento-topic-name').focus()});
  function newSession(date=new Date()){const local=new Date(date);local.setHours(Math.min(23,new Date().getHours()+1),0,0,0);local.setMinutes(local.getMinutes()-local.getTimezoneOffset());el('bento-event-time').value=local.toISOString().slice(0,16);el('bento-event-minutes').value=[15,30,45,60].includes(focusMinutes)?focusMinutes:30;el('bento-event-error').hidden=true;el('bento-event-form').hidden=false;el('bento-event-title').focus({preventScroll:true});void 0}
  function renderWeek(){const week=el('bento-calendar-week');week.replaceChildren();for(let i=0;i<7;i++){const date=new Date();date.setDate(date.getDate()+i);const button=document.createElement('button'),day=document.createElement('small'),number=document.createElement('span');button.type='button';day.textContent=date.toLocaleDateString(undefined,{weekday:'narrow'});number.textContent=date.getDate();button.append(day,number);button.classList.toggle('today',i===0);button.setAttribute('aria-label','Schedule on '+date.toLocaleDateString(undefined,{dateStyle:'full'}));button.addEventListener('click',()=>newSession(date));week.append(button)}}
  el('bento-calendar-new').addEventListener('click',()=>newSession());el('bento-event-cancel').addEventListener('click',()=>{el('bento-event-form').hidden=true;el('bento-calendar-new').focus()});
  el('bento-event-form').addEventListener('submit',event=>{event.preventDefault();try{window.OpenSesameFocusCalendar.add({title:el('bento-event-title').value,start:new Date(el('bento-event-time').value).getTime(),minutes:Number(el('bento-event-minutes').value)});el('bento-event-form').hidden=true;el('bento-event-title').value='';sync();toast('Focus session scheduled.')}catch(error){el('bento-event-error').textContent=error.message;el('bento-event-error').hidden=false}});
  for(const [id,delta] of [['bento-media-prev',-1],['bento-media-next',1]])el(id).addEventListener('click',()=>{const p=window.OpenSesameLocalMedia.preview();if(!p.entries.length)return;window.OpenSesameLocalMedia.select((p.index+delta+p.entries.length)%p.entries.length,false);sync()});
  el('bento-media-loaded').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();event.stopPropagation();el(event.key==='ArrowLeft'?'bento-media-prev':'bento-media-next').click()});
  function paintPlay(id,data,key,tool){const b=el(id),label=data.loaded&&data.ready?(data.playing?'Pause':'Play'):'Open '+tool+' player';let glyph=b.querySelector('[data-play-icon]');if(!glyph){glyph=document.createElement('span');glyph.dataset.playIcon='';b.replaceChildren(glyph)}glyph.innerHTML=icon(data.playing?'pause':'play');b.setAttribute('aria-label',label);b.title=label;b.disabled=busy.has(key)}
  function sync(){
    if(home.hidden||!state.expanded)return;
    const music=musicProvider()?.snapshot()||{},youtube=window.OpenSesameYouTube?.snapshot()||{},media=window.OpenSesameLocalMedia?.snapshot()||{},queue=window.OpenSesameLocalMedia?.preview()||{entries:[],index:-1},calendar=window.OpenSesameFocusCalendar.snapshot();
    el('bento-music-service').value=window.OpenSesameMusic.service;el('bento-music-form').dataset.service=window.OpenSesameMusic.service;el('bento-music-link').placeholder='Paste a '+({spotify:'Spotify',apple:'music',youtube:'YouTube'})[window.OpenSesameMusic.service]+' link…';volumes.forEach(volume=>volume.sync());
    el('bento-music-title').textContent=music.loaded?music.title:'Your soundtrack';el('bento-music-state').textContent=music.loaded?playbackText(music):window.OpenSesameMusic.summary()+' · add a song or playlist';
    home.querySelector('.bento-record').classList.toggle('playing',!!music.playing);paintPlay('bento-music-play',music,'music','music');el('bento-music-play').hidden=!music.loaded;
    el('bento-agenda-count').textContent=focusTopics.length+' topics';
    const agendaKey=JSON.stringify(focusTopics);if(agendaKey!==lastAgenda){lastAgenda=agendaKey;const list=el('bento-agenda-topics');list.replaceChildren();for(const topic of focusTopics.slice(0,2)){const row=document.createElement('button'),name=document.createElement('span'),minutes=document.createElement('small');row.type='button';name.textContent=topic.name;minutes.textContent=Math.round(topic.minutes*10)/10+'m';row.append(name,minutes);row.title='Edit '+topic.name;row.addEventListener('click',()=>{changeScenario('focus');window.OpenSesameFocusCalendar.choose('agenda')});list.append(row)}}
    const blocked=focusRunning||focusTopics.length>=topicLimit();el('bento-topic-form').querySelectorAll('input,button').forEach(field=>field.disabled=blocked);el('bento-topic-help').textContent=focusRunning?'Pause to edit your agenda.':focusTopics.length>=topicLimit()?'Choose a longer session to add more topics.':'';
    el('bento-clock').textContent=time(focusRemaining);el('bento-timer-topic').textContent=(focusRunning?'Now · ':focusRemaining<=0?'Complete · ':focusRemaining<focusMinutes*60?'Paused · ':'Up first · ')+(focusTopics[agendaPosition().index]?.name||'Set your intention');
    const timer=el('bento-timer-play');timer.innerHTML=icon(focusRunning?'pause':'play');timer.setAttribute('aria-label',focusRunning?'Pause focus':focusRemaining<=0?'Start again':focusRemaining<focusMinutes*60?'Resume focus':'Start focus');timer.title=timer.getAttribute('aria-label');
    home.querySelectorAll('[data-focus-minutes]').forEach(b=>{b.setAttribute('aria-pressed',Number(b.dataset.focusMinutes)===focusMinutes);b.disabled=focusRunning;b.title=focusRunning?'Pause to change duration':b.dataset.focusMinutes+' minute focus'});
    const signature=JSON.stringify(calendar.upcoming)+new Date().toDateString();if(signature!==lastCalendar){lastCalendar=signature;renderWeek();el('bento-calendar-day').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});const list=el('bento-upcoming');list.replaceChildren();for(const event of calendar.upcoming.slice(0,2)){const row=document.createElement('div'),label=document.createElement('strong'),date=document.createElement('small');label.textContent=event.title;date.textContent=new Date(event.start).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});row.append(label,date);list.append(row)}if(!calendar.upcoming.length)list.textContent='No upcoming sessions. Choose a day to plan one.'}
    el('bento-youtube-title').textContent=youtube.loaded?youtube.title:'Set the mood';el('bento-youtube-state').textContent=youtube.loaded?playbackText(youtube):'A video, a mix, a little inspiration.';paintPlay('bento-youtube-play',youtube,'youtube','YouTube');
    const videoId=/^[\w-]{11}$/.test(youtube.id||'')?youtube.id:'';if(videoId!==lastImage){lastImage=videoId;const img=el('bento-youtube-art');img.hidden=!videoId;if(videoId)img.src='https://i.ytimg.com/vi/'+videoId+'/mqdefault.jpg';else img.removeAttribute('src')}
    el('bento-media-empty').hidden=!!queue.entries.length;el('bento-media-loaded').hidden=!queue.entries.length;
    if(queue.entries.length){el('bento-media-title').textContent=queue.entries[queue.index]?.title||'Local media';el('bento-media-count').textContent=(queue.index+1)+' / '+queue.entries.length+' · '+playbackText(media);paintPlay('bento-media-play',media,'media','media');for(const id of ['bento-media-prev','bento-media-next'])el(id).disabled=queue.entries.length<2;el('bento-media-play').dataset.kind=queue.entries[queue.index]?.kind||'audio';drawVideo();if(lastMedia!==queue.index){lastMedia=queue.index;el('bento-media-play').style.setProperty('--cover-hue',String(230+(queue.index%5)*25))}}
  }
  // Paint the live source frames; keep a single media element and one audio stream.
  const previewVideo=el('bento-media-video'),sourceVideo=el('local-media'),previewContext=previewVideo.getContext('2d');let previewFrame=0;
  function drawVideo(){
    cancelAnimationFrame(previewFrame);previewFrame=0;
    const visible=!home.hidden&&state.expanded&&!document.hidden&&el('bento-media-play').dataset.kind==='video'&&sourceVideo.videoWidth>0;
    previewVideo.hidden=!visible;el('bento-media-play').classList.toggle('has-video',visible);el('bento-media-play').classList.toggle('is-playing',!sourceVideo.paused&&!sourceVideo.ended);
    if(!visible)return;
    const width=Math.min(960,sourceVideo.videoWidth),height=Math.round(width*sourceVideo.videoHeight/sourceVideo.videoWidth);
    if(previewVideo.width!==width||previewVideo.height!==height){previewVideo.width=width;previewVideo.height=height}
    if(sourceVideo.readyState>=2)try{previewContext.drawImage(sourceVideo,0,0,width,height)}catch{}
    if(!sourceVideo.paused&&!sourceVideo.ended)previewFrame=requestAnimationFrame(drawVideo);
  }
  for(const event of ['loadeddata','play','pause','seeked','ended','emptied'])sourceVideo.addEventListener(event,drawVideo);
  window.addEventListener('open-sesame-view-changed',drawVideo);window.addEventListener('open-sesame-layout',drawVideo);document.addEventListener('visibilitychange',drawVideo);
  el('bento-youtube-art').addEventListener('error',event=>{event.target.hidden=true});
  window.OpenSesameFocusOverview={sync};window.addEventListener('open-sesame-layout',sync);window.addEventListener('open-sesame-view-changed',sync);setInterval(()=>{if(!document.hidden)sync()},750);sync();
})();
